(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.28)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w1y = Math.cos(y*0.016-t*0.24)*18 + Math.sin(x*0.02+t*0.32)*12;
  const wx = Math.sin((x+w1x)*0.012+t*0.15)*8 + w1x;
  const wy = Math.cos((y+w1y)*0.012-t*0.18)*8 + w1y;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.55)*110, 80+Math.cos(t*0.38)*55, 0.075, 2.1, 0],
    [320+Math.cos(t*0.48)*105, 160+Math.sin(t*0.65)*55, 0.095, 1.8, 1.2],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.45+1)*95, 0.055, 2.4, 2.5],
    [120+Math.cos(t*0.75+1)*85, 180+Math.sin(t*0.55+3)*65, 0.11, 1.6, 3.8],
    [360+Math.sin(t*0.38+4)*95, 60+Math.cos(t*0.85+2)*75, 0.065, 2.7, 5.0],
    [240+Math.cos(t*0.32+5)*130, 200+Math.sin(t*0.5)*85, 0.085, 2.0, 0.7],
    [80+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.42+4)*60, 0.1, 1.4, 4.2],
    [400+Math.cos(t*0.52+1)*75, 200+Math.sin(t*0.72+2)*55, 0.08, 2.2, 1.8]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,ph] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS += Math.sin(d*f-t*sp+ph);
    iS += Math.sin(d*f*0.65+t*sp*0.55+1.5+ph*0.5);
    cS += Math.sin(d*f*1.3-t*sp*0.8+ph*2.0)*0.4;
  }
  const act=aS/8, inh=iS/8, cor=cS/8;
  const bg1 = Math.sin(sx*0.035+sy*0.022+t*0.75);
  const bg2 = Math.sin(sx*0.028-sy*0.038+t*1.05);
  const bg3 = Math.sin((sx+sy)*0.11+t*2.3)*0.25;
  const bg4 = Math.sin((sx-sy)*0.095-t*1.9)*0.25;
  const bg = (bg1+bg2)/2 + bg3 + bg4;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2);
  const ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.4);
  const sp2 = Math.sin(dist*0.038+ang*4.5-t*1.1);
  const sp3 = Math.sin(dist*0.06-ang*2-t*2.2)*0.3;
  const spiral = (sp1+sp2)*0.35+sp3;
  const moire = Math.sin(Math.sin(sx*0.08+t)*8+Math.cos(sy*0.07-t*0.7)*6)*0.2;
  const cell = Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.095+t)*0.45;
  const cellW = Math.tanh(cell*1.4)*0.25;
  const pulse = Math.sin(dist*0.03-t*1.8)*Math.exp(-dist*0.003)*0.3;
  const react = Math.tanh((act - inh*0.65 + cor*0.2 + bg*0.25 + spiral + moire + pulse)*2.0);
  const blend = react*0.7 + cellW*0.3;
  const v = blend*0.5+0.5;
  const lum = 0.82+Math.sin(react*Math.PI)*0.18;
  const edge = Math.abs(react)>0.72 ? 1.12+Math.sin(t*3)*0.03 : 0.95+Math.sin(t*2)*0.02;
  const shimmer = 0.96+Math.sin(sx*0.1+sy*0.08+t*4)*0.04;
  const L = lum*edge*shimmer;
  const pal = [
    [6,12,52],[12,42,88],[18,85,118],[28,138,132],[85,170,120],
    [185,185,72],[215,155,65],[205,105,72],[175,60,72],[120,32,62],
    [65,18,52],[30,12,48],[6,12,52]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*L)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*L)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*L)|0
  ];
}
